import{_ as e,o as t,c as n,aj as l}from"./chunks/framework.CX3tclo0.js";const g=JSON.parse('{"title":"agent-harness-is-easy","description":"agentic agent harness带给agentloop的灵活性和可扩展性","frontmatter":{"publish":true,"title":"agent-harness-is-easy","date":"2026-06-27T00:00:00.000Z","category":"astrcodey","tags":["agentic agent harness","agent"],"description":"agentic agent harness带给agentloop的灵活性和可扩展性"},"headers":[],"relativePath":"blog/posts/agent-harness-is-easy.md","filePath":"blog/posts/agent-harness-is-easy.md"}'),s={name:"blog/posts/agent-harness-is-easy.md"};function r(o,a,i,h,d,p){return t(),n("div",null,[...a[0]||(a[0]=[l('<h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>当前设计灵感是基于pi-mono得到的，一切靠扩展，那如果扩展能自由的影响agent在各个生命周期的行为呢</p><h2 id="先说理论" tabindex="-1">先说理论 <a class="header-anchor" href="#先说理论" aria-label="Permalink to &quot;先说理论&quot;">​</a></h2><p>agent 本质上就是对llm的一次调用，只是上下文和工具的不同导致了他不同的行为，那么如果我们对这个运行中上下文进行动态的影响调整呢，我们总是提醒它，我们总是让他去做聪明模型在合适时机该做的事情和思考方向，那么是否小模型也能达到较大模型的效果？</p><h2 id="什么时候并行-什么时候串行" tabindex="-1">什么时候并行，什么时候串行？ <a class="header-anchor" href="#什么时候并行-什么时候串行" aria-label="Permalink to &quot;什么时候并行，什么时候串行？&quot;">​</a></h2><p>llm 除了glm5.2和cluade之外，其他模型是不知道什么时候串行什么时候并行的，如果我们通过提示词影响它的行为，那么我们就可以让它在合适的时机并行，或者串行，甚至是混合模式。</p><p>这里有一个很巧妙的设计，我们是没法在合适的时机提醒它什么时候并行，什么时候串行的，但是如果他在长任务调用总会因为提示词调用todo工具，那么每一次todo工具的调用都会提示他先规划并行还是串行agent或者task的细节，这能明显的影响agent的行为，甚至就让agent在合适的时机分阶段走合适的行为模式。</p><h2 id="plan-模式" tabindex="-1">plan 模式 <a class="header-anchor" href="#plan-模式" aria-label="Permalink to &quot;plan 模式&quot;">​</a></h2><p>在agent越来越强的日子，plan模式的效果越来越弱，它更像是一个让人类先了解agent的计划和思路然后进行优化的一种模式，但是小模型因为参数量的问题，它大概率是不会有一个良好的计划模版实现的，所以我们通常会通过提示词给予一个提示词模版，来让他的输出质量更好更有条理，甚至让他反思一次自己的计划和思路，来达到一个更好的计划质量，可这是怎么做到的？也许不是参数量越大的模型越聪明，是他们更懂得如何思考和规划，而我们也可以通过提示词让小模型也能达到类似的思考和规划来优化其输出结果</p><h2 id="错误恢复" tabindex="-1">错误恢复 <a class="header-anchor" href="#错误恢复" aria-label="Permalink to &quot;错误恢复&quot;">​</a></h2><p>为什么llm会重复走相同的错误路径？仅仅是llm的预测循环了吗？我认为其实质是llm并不知道下一步做什么？如果我们给对应的错误进行处理，给予llm进行下一步的提示，是否能直接让llm走出错误的路径？答案是？百分之80的概率是可以的，为什么不是100%呢？因为我遇到一些神奇的问题比如xml没闭合也会导致llm重复走相同的错误路径还无法恢复！</p><h2 id="更长任务" tabindex="-1">更长任务 <a class="header-anchor" href="#更长任务" aria-label="Permalink to &quot;更长任务&quot;">​</a></h2><p>小llm常常会因为上下文长度的限制习惯走较短路径，我们的todo工具的设计不止是为了让llm在长任务中也能有一个较好的规划和思路，更是让它面对长任务的情况下刷新一次，根据todo的提示时刻让他知道他在做什么，在合适的时机让他知道下一步做什么，优化长任务的表现</p><h2 id="如何更加的agentic-harness但是不丢失本身的优化" tabindex="-1">如何更加的agentic harness但是不丢失本身的优化 <a class="header-anchor" href="#如何更加的agentic-harness但是不丢失本身的优化" aria-label="Permalink to &quot;如何更加的agentic harness但是不丢失本身的优化&quot;">​</a></h2><p>让llm自己选择自己要走的路径，什么时候plan，什么时候todo，什么时候反思，什么时候优化，什么时候并行，什么时候串行！</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>让agent 变得agentic ，增加llm自主度，也许llm并没有你想象的那么脆弱</p>',17)])])}const m=e(s,[["render",r]]);export{g as __pageData,m as default};
